// Builds the alert and the auto-reply for one lead, from the row that
// was just saved (Clean fields). Runs once per item. Plain words only.
// WhatsApp appears only as click-to-chat links (wa.me): nothing here
// sends a WhatsApp message.
const SITE = 'https://aniket-portfolio-six-bice.vercel.app';
const ANIKET_WA = 'https://wa.me/919136582842';
// Set once Cal.com exists (site.bookingUrl on the site). Empty = "reply
// to this email" is the way to book.
const BOOKING_URL = '';

const f = $('Clean fields').item.json;
const first = (f.Name || '').split(' ')[0] || 'there';
const temp = ['hot', 'warm', 'cold'].includes((f['Lead temp'] || '').toLowerCase())
  ? f['Lead temp'].toLowerCase()
  : 'warm';
const src = (f.Source || '').toLowerCase();
const kind = src.startsWith('start-website') ? 'websites'
  : src.startsWith('start-software') ? 'software'
  : src.startsWith('ai-check') ? 'ai'
  : 'form';
const what = { websites: 'free website plan', software: 'free software plan', ai: 'free AI check', form: 'message' }[kind];

// Three lines of their answers: the top three jobs for the AI check,
// the first three answers for a plan.
const lines = (f.Workflow || '').split('\n').map((l) => l.trim()).filter(Boolean);
let recap = [];
if (kind === 'ai') {
  const at = lines.findIndex((l) => l.startsWith('Top 3'));
  recap = at >= 0 ? lines.slice(at + 1, at + 4) : lines.slice(1, 4);
} else if (kind !== 'form') {
  recap = lines.slice(1, 4);
}

// One-tap WhatsApp reply to the LEAD's own number, for Aniket.
const digits = (f.Phone || '').replace(/\D/g, '');
const leadWa = digits.length >= 10
  ? `https://wa.me/${digits}?text=${encodeURIComponent(`Hi ${first}, Aniket here. Thanks for the ${what} on my site. Is now a good time for a quick chat about it?`)}`
  : '';

const guarantee = 'Fixed price, fixed date. If it isn\'t live by the date in writing, you don\'t pay the second half.';
const book = BOOKING_URL
  ? `Book a free 15-minute call here: ${BOOKING_URL}\nOr just reply to this email.`
  : `To book a free 15-minute call, reply with two times that suit you, or message me on WhatsApp: ${ANIKET_WA}`;

const alertSubject = `[${temp.toUpperCase()}] New lead: ${f.Name} (${f.Service}${f.Package ? ', ' + f.Package : ''})`;
const alertBody = [
  `${f.Name} <${f.Email}>`,
  `Lead temp: ${temp.toUpperCase()}`,
  leadWa ? `Reply on WhatsApp (one tap): ${leadWa}` : 'No WhatsApp number given: reply by email (Reply-To is set).',
  `Phone: ${f.Phone || 'not given'}`,
  `Looking for: ${f.Service}`,
  `Package shown: ${f.Package || 'none (contact form)'}`,
  `When: ${f.Timing || 'not asked'}`,
  `Budget: ${f.Budget}`,
  `Company: ${f.Company || 'not given'}`,
  `Source: ${f.Source}`,
  `UTM: ${f['UTM source'] || '-'} / ${f['UTM campaign'] || '-'}`,
  `Landing page: ${f['Landing page'] || '-'}`,
  '',
  'Their answers:',
  f.Workflow,
  '',
  temp === 'hot'
    ? 'HOT: budget fits, wanted soon, number given. A personal reply as soon as you can.'
    : temp === 'warm'
      ? 'WARM: a personal reply the same day.'
      : 'COLD: the follow-up emails cover it; reply personally if it looks worth it.',
  'Saved to the Portfolio leads sheet. Move Stage off "New" once you have replied, which stops the follow-ups.'
].join('\n');

const recapText = recap.length ? `Here is what you told me, in short:\n${recap.map((l) => '- ' + l).join('\n')}\n\n` : '';
let replySubject;
let replyBody;
if (kind === 'websites') {
  replySubject = f.Package ? `Your website plan: ${f.Package.split(' (')[0]}` : 'Your website plan';
  replyBody = `Hi ${first},\n\nThanks for planning your website on my site.\n\n${recapText}The plan suggested the ${f.Package || 'package on your screen'}. That is a starting point, not a quote. On a free 15-minute call we go through your pages and your date, and then you get a one-page proposal with a fixed price.\n\n${guarantee}\n\n${book}\n\nI'll reply within 24 hours, usually sooner.\n\nAniket\n${SITE}`;
} else if (kind === 'software') {
  replySubject = f.Package ? `Your software plan: ${f.Package.split(' (')[0]}` : 'Your software plan';
  replyBody = `Hi ${first},\n\nThanks for planning your software on my site.\n\n${recapText}The plan suggested the ${f.Package || 'package on your screen'}. That is a starting point, not a quote. On a free 15-minute call we go through how the work runs today, and then you get a one-page proposal with a fixed price and a live date. A larger platform is quoted once we have mapped it together.\n\n${guarantee}\n\n${book}\n\nI'll reply within 24 hours, usually sooner.\n\nAniket\n${SITE}`;
} else if (kind === 'ai') {
  replySubject = 'Your free AI check: your top three jobs';
  replyBody = `Hi ${first},\n\nThanks for doing the free AI check on my site.\n\n${recapText}The hours are a rough estimate from your answers, not a measurement. The next step, if you want real numbers, is the AI Roadmap${f.Package ? ' (' + f.Package.replace(/^.*\(/, '').replace(/\)$/, '') + ')' : ''}: a 60-minute session on how your week really runs, then a short written plan with every job ranked by time saved against cost, and a fixed quote for the first build. The fee is taken off that build if you go ahead.\n\n${book}\n\nI'll reply within 24 hours, usually sooner.\n\nAniket\n${SITE}`;
} else {
  replySubject = 'Got your message, I\'ll reply within 24 hours';
  replyBody = `Hi ${first},\n\nThanks for getting in touch. I've got your note about:\n\n"${(f.Workflow || '').slice(0, 280)}"\n\nI'll read it properly and reply within 24 hours, usually sooner. If it isn't something I can genuinely help with, I'll tell you that too.\n\nIn the meantime, here's some of the work: ${SITE}/projects\n\nAniket\n${SITE}`;
}

return { json: { ...f, _alertSubject: alertSubject, _alertBody: alertBody, _replySubject: replySubject, _replyBody: replyBody } };
